def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)
    best_vector = None
    best_versions = None

    def active_dependencies(row):
        return [
            dep for dep in row.get('deps', [])
            if not dep.get('feature') or dep.get('feature') in features
        ]

    def is_acyclic(selected):
        graph = {
            name: [dep['name'] for dep in active_dependencies(row)]
            for name, row in selected.items()
        }
        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for neighbor in graph[name]:
                if not visit(neighbor):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(selected, pending):
        nonlocal best_vector, best_versions

        if not pending:
            if not is_acyclic(selected):
                return
            versions = {name: row['version'] for name, row in selected.items()}
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name, low, high = pending[0]
        rest = pending[1:]

        if name not in packages:
            return

        if name in selected:
            version = selected[name]['version']
            if low <= version <= high:
                search(selected, rest)
            return

        for row in options(
            packages[name], low, high,
            blocked.get(name, []),
            pins.get(name),
        ):
            next_selected = dict(selected)
            next_selected[name] = row
            dependencies = [
                (dep['name'], dep['min'], dep['max'])
                for dep in active_dependencies(row)
            ]
            search(next_selected, dependencies + rest)

    pending_roots = [
        (name, bounds[0], bounds[1]) for name, bounds in roots.items()
    ]
    search({}, pending_roots)

    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
